export default function nextFeedAlert({ notifications, previousState, lastReceipt }) {
  if (!Array.isArray(notifications))
    throw new Error("Expected the complete selected notification array.");
  let sent = 0;
  if (previousState === null) {
    if (lastReceipt !== null)
      throw new Error("Unexpected Telegram receipt before delivery starts.");
  } else {
    if (
      !previousState ||
      !Number.isSafeInteger(previousState.sent) ||
      previousState.sent < 0 ||
      previousState.sent >= notifications.length
    )
      throw new Error("Invalid Telegram delivery state.");
    if (!lastReceipt || !Number.isSafeInteger(lastReceipt.messageId))
      throw new Error("Telegram returned no message identifier; inspect the chat before retrying.");
    sent = previousState.sent + 1;
  }
  const text = notifications[sent]?.text ?? notifications.at(-1)?.text ?? "No matching entries.";
  if (typeof text !== "string" || !text || text.length > 4096)
    throw new Error("Invalid Telegram alert text.");
  return { state: { sent }, sent, more: sent < notifications.length, text };
}

