export default async function commitFeedWatermark(
  { stateKey, nextTimestamp, count, sent },
  context,
) {
  if (sent !== count)
    throw new Error("Do not advance the watermark before all notifications succeed.");
  if (count) await context.state.set(stateKey, nextTimestamp);
  return { sent, watermark: nextTimestamp };
}
